import {RigidWorld} from './rigid-world.mjs';
import {beginRecovery,stepRecovery} from './recovery.mjs';
import {assemblyPhysics} from './assembly.mjs';
import {Vector3 as V,Quaternion as Q,Matrix4 as M} from './three.mjs';
const copy=structuredClone;
const structuralRoles=new Set(['home','barn','store','shelter','enclosure','playground']);
export function selectRanchCollisionMeshes(object,plan){
 const keys=new Set(plan.placements.filter(p=>structuralRoles.has(p.role)).map(p=>p.id)),meshes=[];
 object.traverse(mesh=>{if(!mesh.isMesh||!mesh.geometry?.attributes.position)return;const materials=Array.isArray(mesh.material)?mesh.material:[mesh.material];let solid=materials.some(m=>m.userData?.seasonRole==='ground');for(let p=mesh;p&&p!==object;p=p.parent)if(keys.has(p.userData.motionKey))solid=true;if(solid)meshes.push(mesh);});return meshes;
}
/** A local integration adapter, with kinematic tile manipulation explicitly distinguished from dynamic drops. */
export function createRanchPhysics({root,assembly,tileObjects,radiusMetres,renderUnitsPerMetre=.1,entities,behavior,snapshotBehavior,restoreBehavior,fixtures=()=>[],profiles={}}){
 if(!root||!entities||!behavior?.acquire||!behavior?.release||!snapshotBehavior||!restoreBehavior)throw Error('Explicit scene, pose ownership and transactional behavior callbacks required');
 root.updateWorldMatrix(true,true);
 const initialEntities=entities(),entityRoots=new Set(initialEntities.map(e=>e.body));
 const bindings=fixtures().map(f=>({...f,base:new M().multiplyMatrices(root.matrixWorld.clone().invert(),f.object.matrixWorld)}));
 const fixtureMeshes=id=>{const meshes=[];for(const f of bindings.filter(f=>f.tileId===id))f.object.traverse(mesh=>{if(!mesh.isMesh||!mesh.geometry?.attributes.position)return;for(let p=mesh;p&&p!==f.object.parent;p=p.parent)if(entityRoots.has(p))return;meshes.push(mesh);});return meshes;};
 const objects=new Map(tileObjects.map(t=>[t.id,t.object])),world=assemblyPhysics({World:RigidWorld,assembly,radiusMetres,renderUnitsPerMetre,profiles,tileMeshes:new Map(tileObjects.map(t=>[t.id,{root:t.object,meshes:[...new Set([...t.collisionMeshes,...fixtureMeshes(t.id)])]}]))}),homeFrames=new Map([...world.tiles].map(([id,t])=>[id,copy(t.frame)]));
 const renderFrame=f=>new M().compose(new V(...f.position).multiplyScalar(renderUnitsPerMetre),new Q(...f.rotation),new V(1,1,1));
 const atHome=id=>{const t=world.tiles.get(id),home=homeFrames.get(id);return !!t&&!!home&&!t.motion&&t.frame.position.every((v,k)=>Math.abs(v-home.position[k])<1e-6)&&Math.abs(t.frame.rotation.reduce((n,v,k)=>n+v*home.rotation[k],0))>1-1e-8;};
 let owned=new Set(),held=null,transaction=null,transactionTile=null,lastEvents=[],ending=false;
 function list(){const entries=entities();for(const e of entries)if(!e.body||!Array.isArray(e.centerOffset)||e.centerOffset.length!==3||!e.centerOffset.every(Number.isFinite))throw Error('Entity body and explicit world-metre centerOffset required');return new Map(entries.map(e=>[e.bodyId,e]));}
 function sync(dt=0){const current=list();for(const id of world.bodies.keys())if(!current.has(id)){world.bodies.delete(id);owned.delete(id);}for(const [id,e]of current){let b=world.bodies.get(id);if(b?.storyId!==e.storyId){world.bodies.delete(id);owned.delete(id);b=null;}const position=e.position.map((v,k)=>v+e.centerOffset[k]);if(!b)b=world.addBody({id,storyId:e.storyId,position,rotation:new Q().copy(root.getWorldQuaternion(new Q())).invert().multiply(e.body.getWorldQuaternion(new Q())).toArray(),radius:e.radius,mass:e.mass??1,kinematic:true});if(!owned.has(id)){b.rotation=new Q().copy(root.getWorldQuaternion(new Q())).invert().multiply(e.body.getWorldQuaternion(new Q())).toArray();b.angularVelocity=[0,0,0];b.velocity=dt>0?position.map((v,k)=>(v-b.position[k])/dt):[0,0,0];b.position=position;b.kinematic=true;world.membership(b);}}return current;}
 function applyTiles(){for(const [id,object]of objects){const f=world.tiles.get(id).frame;object.position.fromArray(f.position).multiplyScalar(renderUnitsPerMetre);object.quaternion.fromArray(f.rotation);object.updateWorldMatrix(true,true);}root.updateWorldMatrix(true,true);for(const f of bindings){const tile=world.tiles.get(f.tileId);if(!tile)continue;const delta=new M().multiplyMatrices(renderFrame(tile.frame),renderFrame(homeFrames.get(f.tileId)).invert()),target=new M().multiplyMatrices(root.matrixWorld,delta).multiply(f.base);f.object.parent.updateWorldMatrix(true,false);const local=new M().multiplyMatrices(f.object.parent.matrixWorld.clone().invert(),target);local.decompose(f.object.position,f.object.quaternion,f.object.scale);f.object.updateWorldMatrix(false,true);}}
 function applyBodies(current,ids=owned){root.updateWorldMatrix(true,true);for(const id of ids){const e=current.get(id),b=world.bodies.get(id);if(!e||!b)continue;const offset=owned.has(id)?new V(...e.centerOffset).applyQuaternion(new Q(...b.rotation)).toArray():e.centerOffset,feet=b.position.map((v,k)=>v-offset[k]),point=root.localToWorld(new V(...feet).multiplyScalar(renderUnitsPerMetre));e.body.parent.updateWorldMatrix(true,false);e.body.position.copy(e.body.parent.worldToLocal(point));if(owned.has(id)){const orientation=root.getWorldQuaternion(new Q()).multiply(new Q(...b.rotation));e.body.quaternion.copy(e.body.parent.getWorldQuaternion(new Q()).invert().multiply(orientation));}e.body.updateWorldMatrix(false,true);}}
 function events(){const batch=world.drainEvents();for(const event of batch){lastEvents.push(event);behavior.handle?.(event);}return batch;}
 const pose=o=>({position:o.position.toArray(),rotation:o.quaternion.toArray(),euler:o.rotation.toArray(),scale:o.scale.toArray()});
 const setPose=(o,p)=>{o.position.fromArray(p.position);if(p.euler)o.rotation.fromArray(p.euler);else o.quaternion.fromArray(p.rotation);o.scale.fromArray(p.scale);};
 function restoreVisuals(saved){if(!saved.visuals){applyBodies(list(),world.bodies.keys());return;}for(let i=0;i<bindings.length;i++)if(saved.visuals.fixtures[i])setPose(bindings[i].object,saved.visuals.fixtures[i]);const current=list();for(const e of saved.visuals.entities){const live=current.get(e.id);if(live?.storyId===e.storyId)setPose(live.body,e.pose);}root.updateWorldMatrix(true,true);}
 function snapshot(){return {version:1,visuals:{entities:[...list()].map(([id,e])=>({id,storyId:e.storyId,pose:pose(e.body)})),fixtures:bindings.map(f=>pose(f.object))},physics:world.snapshot(),behavior:copy(snapshotBehavior()),owned:[...owned],held,ending,transactionTile};}
 function restore(saved){if(saved?.version!==1)throw Error('Unsupported adapter save');const before=snapshot();try{world.restore(saved.physics);restoreBehavior(copy(saved.behavior));owned=new Set(saved.owned);held=saved.held;ending=saved.ending;transactionTile=saved.transactionTile??null;applyTiles();restoreVisuals(saved);lastEvents=[];}catch(error){world.restore(before.physics);restoreBehavior(before.behavior);owned=new Set(before.owned);held=before.held;ending=before.ending;transactionTile=before.transactionTile??null;applyTiles();restoreVisuals(before);throw error;}}
 sync();world.drainEvents();
 return {
  world,capabilities:Object.freeze({kinematicTiles:true,sphereContacts:true,dynamicTileDrop:true,angularBodyDynamics:true,routeTopologyRebuild:false}),
  begin(tileId,{response='panic'}={}){if(held||transaction)throw Error('Finish or cancel current manipulation');if(!objects.has(tileId))throw Error('Unknown tile');sync();transaction=snapshot();transactionTile=tileId;held=tileId;ending=false;const ids=[...world.bodies.values()].filter(b=>b.tileId===tileId).map(b=>b.id);try{behavior.acquire(ids,{mode:response});for(const id of ids){owned.add(id);world.bodies.get(id).kinematic=false;world.bodies.get(id).restRotation=[...world.bodies.get(id).rotation];}world.setConnected(tileId,false);world.emit('manipulation',{tileId,phase:'begin',bodyIds:ids,response});for(const bodyId of ids)world.emit('manipulation',{tileId,bodyId,phase:'begin',response});events();}catch(error){restore(transaction);transaction=null;throw error;}return ids;},
  move(target,durationSeconds=1/60){if(!held)throw Error('No held tile');world.driveFrame(held,target,durationSeconds);},
  grab(tileId){if(!transaction||tileId!==transactionTile)throw Error('Re-grab the tile in the current transaction');if(held&&held!==tileId)throw Error('Another tile is held');world.stopFrame(tileId);const t=world.tiles.get(tileId);delete t.releaseSampleTime;delete t.releaseVelocity;delete t.releaseAngularVelocity;held=tileId;ending=false;},
  drop(){if(!held)return;world.dropFrame(held);world.emit('manipulation',{tileId:held,phase:'drop'});held=null;ending=false;events();},
  end(){if(!held)return;world.stopFrame(held);world.emit('manipulation',{tileId:held,phase:'end'});held=null;ending=true;events();},
  returnTile(tileId,durationSeconds=.5){if(!homeFrames.has(tileId))throw Error('Unknown tile');world.driveFrame(tileId,homeFrames.get(tileId),durationSeconds);ending=true;},
  cancel(){if(transaction){restore(transaction);transaction=null;}},
  update(dt){if(!Number.isFinite(dt)||dt<0||dt>1)throw Error('Physical dt must be 0..1 seconds');const current=sync(dt);if(owned.size||[...world.tiles.values()].some(t=>t.motion||t.dynamic)){for(const id of owned){const b=world.bodies.get(id);if(b){b.righting=!!(ending&&!held&&atHome(b.tileId));if(b.righting&&world.tiles.get(b.tileId)?.connected)stepRecovery(b,dt);}}world.advance(dt);applyTiles();applyBodies(current,world.bodies.keys());events();}
   if(ending&&!held){for(const [id,t]of world.tiles){const home=homeFrames.get(id);if(atHome(id)&&!t.connected)world.setConnected(id,true);}
    for(const id of [...owned]){const e=current.get(id),b=world.bodies.get(id);if(!e||!b||!b.settled||!atHome(b.tileId)||!world.tiles.get(b.tileId)?.connected)continue;const position=b.position.map((v,k)=>v-e.centerOffset[k]);if(new V(0,1,0).applyQuaternion(new Q(...b.rotation)).y>=.995&&behavior.release(id,{position,tileId:b.tileId})===true){owned.delete(id);b.kinematic=true;delete b.recovery;}else if(!b.recovery&&(b.recoveryAttempts??0)<3&&world.time>=(b.nextRecoveryAt??0)&&behavior.recoveryTarget){b.recoveryAttempted=false;b.recoveryAttempts=(b.recoveryAttempts??0)+1;b.nextRecoveryAt=world.time+1;beginRecovery(b,behavior.recoveryTarget(id,{position,tileId:b.tileId,minDistance:new V(0,1,0).applyQuaternion(new Q(...b.rotation)).y<.995?.4:0,clearance:.25}),e.centerOffset);}}
    if(!owned.size)ending=false;events();}
  },
  snapshot,restore,drainEvents(){return lastEvents.splice(0);},get owned(){return [...owned];},get held(){return held;},
  dispose(){if(transaction&&(held||owned.size))restore(transaction);world.bodies.clear();world.dispose();lastEvents=[];}
 };
}
